function navigate(path:string){history.pushState({},'',path);window.dispatchEvent(new PopStateEvent('popstate'))}
function Logo({compact=false}:any){return <div className={'official-logo '+(compact?'compact':'')}><img src={compact?'/clara-marca-oficial.png':'/clara-logo-oficial.png'} alt="Clara BPO Financeiro"/></div>}
function Pill({children,tone='gray'}:any){return <span className={'pill '+tone}>{children}</span>}
function Kpi({icon:Icon,title,value,sub,tone='blue',onClick}:any){return <button className={'kpi-card '+tone+(onClick?' clickable':'')} onClick={onClick}><div className="kpi-icon"><Icon/></div><div><span>{title}</span><strong>{value}</strong><small>{sub}</small></div></button>}
function Empty({icon:Icon=CircleAlert,title,sub}:any){return <div className="empty"><Icon/><div><b>{title}</b>{sub&&<span>{sub}</span>}</div></div>}
function Spinner(){return <span className="spinner"/>}
function SortHead({id,label,sort,onSort}:any){const active=sort.key===id;return <button className={'sort-head '+(active?'active':'')} onClick={()=>onSort(id)}>{label}<b>{active?(sort.order==='asc'?'↑':'↓'):'↕'}</b></button>}
function LineChart({values}:any){const clean=(values||[]).map((x:any)=>num(x));const max=Math.max(...clean,1),min=Math.min(...clean,0),range=Math.max(1,max-min);const pts=clean.map((v:number,i:number)=>`${(i/(Math.max(1,clean.length-1)))*100},${88-((v-min)/range)*70}`).join(' ');return <div className="line-chart"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><line x1="0" y1="88" x2="100" y2="88"/><line x1="0" y1="55" x2="100" y2="55"/><line x1="0" y1="22" x2="100" y2="22"/><polyline points={pts}/>{clean.map((v:number,i:number)=>{const x=(i/(Math.max(1,clean.length-1)))*100,y=88-((v-min)/range)*70;return <circle key={i} cx={x} cy={y} r="1.8"/>})}</svg><div className="chart-months">{clean.map((_:any,i:number)=><span key={i}>{new Date(2026,i,1).toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</span>)}</div></div>}
function RevenueExpenseChart({revenue,expenses}:any){
  const a=(revenue||[]).map((x:any)=>num(x)),b=(expenses||[]).map((x:any)=>Math.abs(num(x))),len=Math.max(a.length,b.length,1)
  while(a.length<len)a.push(0);while(b.length<len)b.push(0)
  const max=Math.max(...a,...b,1)
  const pts=(arr:number[])=>arr.map((v:number,i:number)=>`${(i/(Math.max(1,len-1)))*100},${86-(v/max)*68}`).join(' ')
  return <div className="finance-chart"><div className="finance-legend"><span className="rev-dot"/>Receita líquida <span className="exp-dot"/>Despesas</div><svg viewBox="0 0 100 100" preserveAspectRatio="none"><line x1="0" y1="86" x2="100" y2="86"/><line x1="0" y1="54" x2="100" y2="54"/><line x1="0" y1="22" x2="100" y2="22"/><polyline className="revenue-line" points={pts(a)}/><polyline className="expense-line" points={pts(b)}/>{a.map((v:number,i:number)=><circle className="revenue-point" key={'r'+i} cx={(i/(Math.max(1,len-1)))*100} cy={86-(v/max)*68} r="1.5"/>)}{b.map((v:number,i:number)=><circle className="expense-point" key={'e'+i} cx={(i/(Math.max(1,len-1)))*100} cy={86-(v/max)*68} r="1.5"/>)}</svg><div className="chart-months">{Array.from({length:len},(_,i)=><span key={i}>{new Date(2026,i,1).toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</span>)}</div></div>
}


function AuthScreen({onAuth}:any){
  const[mode,setMode]=useState<'login'|'register'>('login'),[busy,setBusy]=useState(false),[error,setError]=useState(''),[show,setShow]=useState(false),[status,setStatus]=useState<any>(null)
  const[form,setForm]=useState({name:'',email:'',password:'',companyName:''})
  useEffect(()=>{fetch('/api/auth/status').then(r=>r.json()).then(setStatus).catch(()=>{})},[])
  async function submit(e:any){e.preventDefault();setBusy(true);setError('');try{const payload=await apiJson(mode==='login'?'/api/auth/login':'/api/auth/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form)});localStorage.setItem(TOKEN_KEY,payload.token);if(payload.companies?.[0]?.id)localStorage.setItem(COMPANY_KEY,payload.companies[0].id);onAuth({user:payload.user,companies:payload.companies||[]});navigate('/app')}catch(err:any){setError(err.message)}finally{setBusy(false)}}
  return <div className="auth-page">
    <div className="auth-window">
      <section className="auth-brand-panel">
        <div className="auth-brand-inner">
          <Logo/>
          <div className="auth-copy">
            <h1>Clareza para<br/>cuidar do <em>seu negócio.</em></h1>
            <p>Organize o financeiro da sua empresa com tecnologia inteligente, atendimento próximo e uma experiência feita para simplificar a rotina.</p>
            <div className="auth-benefits">
              <div><BarChart3/><span><b>Visão clara do seu financeiro</b><small>Indicadores e relatórios que ajudam nas melhores decisões.</small></span></div>
              <div><RefreshCcw/><span><b>Conciliação automática</b><small>Integrações que reduzem erros e economizam tempo.</small></span></div>
              <div><Users/><span><b>Atendimento especializado</b><small>Um sistema pensado para apoiar sua rotina.</small></span></div>
            </div>
          </div>
          <img className="clara-character" src="/clara-personagem-mockup.png" alt="" aria-hidden="true"/>
          <div className="auth-orbit"><span/><span/><span/></div>
          <small className="brand-footer">Clara BPO Financeiro · gestão simples e inteligente</small>
        </div>
      </section>
      <section className="auth-form-panel">
        <form className="auth-card" onSubmit={submit}>
          <span className="eyebrow">{mode==='login'?'ENTRAR':'CRIAR CONTA'}</span>
          <h2>{mode==='login'?'Bem-vindo':'Comece no Clara'}</h2>
          <p>{mode==='login'?'Use o usuário cadastrado para acessar as configurações compartilhadas da sua empresa.':'Crie sua empresa e o primeiro usuário administrador.'}</p>
          {mode==='register'&&<><label>Nome<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="Seu nome"/></label><label>Empresa<input required value={form.companyName} onChange={e=>setForm({...form,companyName:e.target.value})} placeholder="Nome da empresa"/></label></>}
          <label>E-mail<div className="input-icon"><Users/><input type="email" required value={form.email} onChange={e=>setForm({...form,email:e.target.value})} placeholder="seu@email.com"/></div></label>
          <label>Senha<div className="input-icon"><Lock/><input type={show?'text':'password'} minLength={mode==='register'?8:1} required value={form.password} onChange={e=>setForm({...form,password:e.target.value})} placeholder={mode==='register'?'Mínimo 8 caracteres':'Sua senha'}/><button type="button" className="eye-btn" onClick={()=>setShow(!show)} aria-label="Mostrar ou ocultar senha"><Eye/></button></div></label>
          {error&&<div className="form-error"><AlertTriangle/>{error}</div>}
          <button className="primary big" disabled={busy}>{busy?<Spinner/>:mode==='login'?'Entrar':'Criar conta'}</button>
          <div className="auth-divider"><span>ou</span></div>
          <button type="button" className="link-row" onClick={()=>{setMode(mode==='login'?'register':'login');setError('')}}><span>{mode==='login'?'Ainda não possui acesso?':'Já possui uma conta?'}</span><b>{mode==='login'?'Criar conta':'Entrar'} <ArrowUpRight/></b></button>
          <button type="button" className="link-row" onClick={()=>navigate('/demonstracao')}><span>Quer conhecer o sistema primeiro?</span><b>Abrir demonstração <ArrowUpRight/></b></button>
          {status&&!status.masterReady&&<div className="setup-note"><ShieldCheck/><span><b>Ativação do usuário master</b><small>Configure <code>MASTER_INITIAL_PASSWORD</code> no Railway para liberar {status.masterEmail}.</small></span></div>}
        </form>
        <small className="auth-footer">© 2026 Clara BPO Financeiro</small>
      </section>
    </div>
  </div>
}

