function PageTitle({eyebrow,title,sub,actions}:any){return <div className="page-title"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{sub}</p></div>{actions&&<div className="page-actions">{actions}</div>}</div>}
function CardHead({title,sub,action}:any){return <div className="card-head"><div><b>{title}</b>{sub&&<span>{sub}</span>}</div>{action}</div>}
function DreCompact({sections,result}:any){return <div className="dre-compact">{(sections||[]).map((s:any,i:number)=><div key={s.key||s.label||i} className="dre-block"><div className="dre-section"><b>{s.label}</b><b>{fmt(s.total)}</b></div>{(s.accounts||s.items||[]).map((a:any,j:number)=>{const label=Array.isArray(a)?a[0]:(a.code?`${a.code} · `:'')+a.name,value=Array.isArray(a)?a[1]:a.amount;return <div className="dre-row" key={a.id||j}><span>{label}</span><b>{fmt(value)}</b></div>})}</div>)}<div className="dre-result"><b>RESULTADO</b><b>{fmt(result)}</b></div></div>}
function SimpleTxTable({rows,onRow}:any){return <div className="data-table"><div className="tr head"><b>Competência</b><b>Descrição</b><b>Forma</b><b>Plano de contas</b><b>Status</b><b>Valor</b></div>{rows.map((r:any)=><button key={r.id} className="tr row" onClick={()=>onRow?.(r)}><span>{dateFmt(r.effective_competence_at||r.competence_at||r.occurred_at)}</span><b>{r.description}</b><span>{r.payment_method||'—'}</span><span>{r.account_name||r.category||'A classificar'}</span><Pill tone={r.financial_status==='OPEN'?'orange':'green'}>{r.financial_status==='OPEN'?'Aberto':r.direction==='ENTRADA'?'Recebido':'Pago'}</Pill><strong className={num(r.amount)>=0?'money in':'money out'}>{fmt(r.amount)}</strong></button>)}</div>}
function ReconRow({left,right,confidence}:any){return <div className="recon-row"><div><b>{left}</b><span>Fato econômico</span></div><RefreshCcw/><div><b>{right}</b><span>Movimento de caixa</span></div><Pill tone="green">{confidence}</Pill></div>}

